<?php
require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$rid=(int)($_POST['recipe_id']??0);if(!$rid){$p->prepare("INSERT INTO recipes(name,product_id,packaging_cost,labor_cost,notes)VALUES(?,?,?,?,?)")->execute([$_POST['name'],$_POST['product_id']?:null,$_POST['packaging_cost'],$_POST['labor_cost'],$_POST['notes']]);$rid=(int)$p->lastInsertId();}if(isset($_POST['component_product_id']))$p->prepare("INSERT INTO recipe_items(recipe_id,component_product_id,qty)VALUES(?,?,?)")->execute([$rid,$_POST['component_product_id'],$_POST['qty']]);go('recipes.php?edit='.$rid);}
if(isset($_GET['delitem'])){$p->prepare("DELETE FROM recipe_items WHERE id=?")->execute([(int)$_GET['delitem']]);go('recipes.php?edit='.(int)$_GET['edit']);}
$products=$p->query("SELECT id,name,cost,price FROM products ORDER BY name")->fetchAll();$recipes=$p->query("SELECT r.*,p.name product FROM recipes r LEFT JOIN products p ON p.id=r.product_id ORDER BY r.name")->fetchAll();$edit=null;$items=[];if(isset($_GET['edit'])){$s=$p->prepare("SELECT * FROM recipes WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();$s=$p->prepare("SELECT ri.*,p.name,p.cost FROM recipe_items ri JOIN products p ON p.id=ri.component_product_id WHERE ri.recipe_id=?");$s->execute([(int)$_GET['edit']]);$items=$s->fetchAll();}page_head('Fichas de montagem');?>
<div class="grid g2"><div class="card"><h2>Nova composição</h2><form method="post"><?=csrf_field()?><input type="hidden" name="recipe_id" value="<?=$edit['id']??''?>"><?php if(!$edit):?><label>Nome da composição</label><input name="name" required><label>Produto final</label><select name="product_id"><option value="">Sem vínculo</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><div class="grid g2"><div><label>Embalagem</label><input name="packaging_cost" type="number" step=".01" value="0"></div><div><label>Mão de obra</label><input name="labor_cost" type="number" step=".01" value="0"></div></div><label>Notas</label><textarea name="notes"></textarea><button class="primary">Criar ficha</button><?php else:?><h3><?=e($edit['name'])?></h3><label>Componente</label><select name="component_product_id"><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?> • <?=money($x['cost'])?></option><?php endforeach;?></select><label>Quantidade</label><input name="qty" type="number" step=".01" value="1"><button class="primary">Adicionar componente</button><?php endif;?></form></div>
<div class="card"><h2>Fichas cadastradas</h2><?php foreach($recipes as $r):?><p><a class="btn" href="?edit=<?=$r['id']?>"><?=e($r['name'])?></a> <?=e($r['product']?:'')?></p><?php endforeach;?></div></div>
<?php if($edit):$componentCost=array_sum(array_map(fn($x)=>$x['cost']*$x['qty'],$items));$total=$componentCost+$edit['packaging_cost']+$edit['labor_cost'];?><div class="card"><h2>Componentes — custo total <?=money($total)?></h2><div class="table"><table><tr><th>Produto</th><th>Qtd.</th><th>Custo</th><th></th></tr><?php foreach($items as $i):?><tr><td><?=e($i['name'])?></td><td><?=$i['qty']?></td><td><?=money($i['cost']*$i['qty'])?></td><td><a class="btn danger" href="?edit=<?=$edit['id']?>&delitem=<?=$i['id']?>">Excluir</a></td></tr><?php endforeach;?></table></div></div><?php endif;?><?php page_foot();?>